INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c8040000-0000-4000-8000-000000000001', 'c8030000-0000-4000-8000-000000000001', 1, 'TEXT', 'Câu hỏi suy luận ở band 8 hỏi điều cả bài ngụ ý, không phải điều một câu nói. Hãy theo dõi cấu trúc lập luận: nhận định phổ biến, rồi "a closer look complicates", rồi điều tác giả thực sự nghĩ. Đáp án đúng thường mang giới hạn ("alone", "less than assumed"); đáp án sai thường cực đoan hoặc chỉ lặp lại quan điểm mà tác giả đang phản bác.');
