INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c8040000-0000-4000-8000-000000000004', 'c8030000-0000-4000-8000-000000000002', 1, 'TEXT', 'Bài thi Reading có 60 phút cho ba bài và 40 câu, khoảng 20 phút mỗi bài. Hãy đọc lướt toàn bài trong 2–3 phút để có bản đồ ý, rồi định vị câu trả lời bằng từ khóa khó thay thế như tên riêng, số, thuật ngữ ("fungi", "fertiliser"). Đừng dừng quá lâu ở một câu: đánh dấu, làm tiếp và quay lại sau. Đọc kỹ chỉ phần chứa đáp án.');
