INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c8040000-0000-4000-8000-000000000007', 'c8030000-0000-4000-8000-000000000003', 1, 'TEXT', 'Người nói ở band 8 thường không nói thẳng "bạn sai". Giảng viên khen trước rồi lưu ý: "A third is the figure usually quoted. Be careful to say where it comes from" nghĩa là số liệu có thể bị nghi ngờ. "Do check that..." là một lời nhắc có lo ngại thật. Chú ý cấu trúc "I do have one concern, though" và các từ "though", "but", "careful": ý chính nằm ở đó.');
