INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c8040000-0000-4000-8000-000000000010', 'c8030000-0000-4000-8000-000000000004', 1, 'TEXT', 'Part 4 là một bài giảng không ngắt quãng, nhiều số liệu và quan hệ nhân quả. Giảng viên báo cấu trúc: "Let me begin with", "So what do...", "Of course", "To sum up". Ghi chú theo khung: ý chính, số liệu, ví dụ. Phân biệt ý chính với ví dụ minh họa: thí nghiệm cốc cà phê là bằng chứng, không phải kết luận. Câu "My advice is..." ở cuối thường là đáp án.');
