INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c8040000-0000-4000-8000-000000000013', 'c8030000-0000-4000-8000-000000000005', 1, 'TEXT', 'Văn phong học thuật tránh cảm xúc và khẳng định tuyệt đối. Thay "Everybody knows that social media is terrible" bằng "There is growing evidence that heavy social media use may harm young people''s sleep". Dùng từ giảm nhẹ (may, tend to, arguably), danh từ hóa ("the rise in prices" thay cho "prices went up a lot") và chủ ngữ khách quan. Không viết tắt (don''t), không hỏi tu từ, không dùng "you" để nói chung.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c8040000-0000-4000-8000-000000000013', (SELECT id FROM knowledge_points WHERE code = 'W80_ACADEMIC_STYLE'));
