INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c8070000-0000-4000-8000-000000000041', 'c8060000-0000-4000-8000-000000000041', 1, 'Which sentence has the most appropriate academic style?', '[{"optionKey": "A", "content": "There is evidence that long working hours may reduce productivity.", "sortOrder": 1}, {"optionKey": "B", "content": "Working too much is totally useless.", "sortOrder": 2}, {"optionKey": "C", "content": "You know that working long hours is bad.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'It is hedged, impersonal and precise.', 'MEDIUM', 'PUBLISHED');
