INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c8040000-0000-4000-8000-000000000015', 'c8030000-0000-4000-8000-000000000006', 1, 'TEXT', 'Lập luận ở band 8 thừa nhận phản biện rồi giới hạn hoặc phản bác nó: "Admittedly, a sugar tax raises prices for poorer families; however, the revenue could fund free school meals." Kết luận có điều kiện ("provided that", "as long as") cho thấy bạn thấy được độ phức tạp của vấn đề mà vẫn giữ quan điểm rõ. Nhượng bộ không có nghĩa là đổi ý: phần phản bác phải mạnh hơn phần thừa nhận.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c8040000-0000-4000-8000-000000000015', (SELECT id FROM knowledge_points WHERE code = 'W80_NUANCED_ARGUMENT'));
